public class OrderSaga : MassTransitStateMachine<OrderSagaState>
{
    public State AwaitingPayment { get; private set; } = null!;
    public State Compensating { get; private set; } = null!;
    public Event<PaymentOk> PaymentOk { get; private set; } = null!;
    public Event<PaymentTimeout> PaymentTimeout { get; private set; } = null!;

    public OrderSaga()
    {
        InstanceState(x => x.CurrentState);
        Event(() => PaymentOk, e => e.CorrelateById(m => m.Message.OrderId));
        Initially(When(Submitted)
            .TransitionTo(AwaitingPayment)
            .Publish(c => new ReserveStock(c.Saga.OrderId))
            .Schedule(PaymentTimeout, c => new PaymentTimeout(c.Saga.OrderId), TimeSpan.FromHours(1)));
        During(AwaitingPayment, When(PaymentOk).TransitionTo(Done));
        DuringAny(When(PaymentTimeout).TransitionTo(Compensating)
            .Publish(c => new ReleaseCredit(c.Saga.OrderId)).Finalize());
    }
}

