[Function(nameof(OrderOrchestrator))]
public static async Task Run([OrchestrationTrigger] TaskOrchestrationContext ctx)
{
    var order = ctx.GetInput<Order>();
    await ctx.CallActivityAsync("ReserveCredit", order);
    using var cts = new CancellationTokenSource();
    var pay = ctx.CallActivityAsync("TakePayment", order);
    var timeout = ctx.CreateTimer(TimeSpan.FromHours(1), cts.Token);
    if (await Task.WhenAny(pay, timeout) == timeout)
        await ctx.CallActivityAsync("ReleaseCredit", order);   // compensate
    else
        cts.Cancel();                                          // stop loser
    await ctx.CallActivityAsync("Ship", order);
}

var machine = new StateMachine<OrderState, OrderTrigger>(
    () => order.State, s => order.State = s);

machine.Configure(OrderState.AwaitingPayment)
       .Permit(OrderTrigger.PaymentOk, OrderState.AwaitingStock)
       .Permit(OrderTrigger.Timeout, OrderState.Compensating)
       .OnEntryAsync(async () => await _repo.SaveAsync(order));

await machine.FireAsync(OrderTrigger.PaymentOk);   // guard + persist
